class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[0] * (k + 1) for _ in range(n)]

        for l in range(n - 1, -1, -1):
            new_dp = [[0] * (k + 1) for _ in range(n)]

            for rem in range(k + 1):
                new_dp[l][rem] = 1

            for r in range(l + 1, n):
                diff = abs(ord(s[l]) - ord(s[r]))
                cost = min(diff, 26 - diff)

                for rem in range(k + 1):
                    best = max(dp[r][rem], new_dp[r - 1][rem])

                    if rem >= cost:
                        best = max(best, dp[r - 1][rem - cost] + 2)

                    new_dp[r][rem] = best

            dp = new_dp

        return dp[n - 1][k]
